: 1, "old_str_end_line_number_1": 34, "new_str_1": "import React, { useState, useEffect, useCallback } from 'react'\nimport { motion, AnimatePresence } from 'framer-motion'\nimport { Heart, Sparkles, ChevronLeft, ChevronRight, MapPin, Calendar, Camera, ImageIcon } from 'lucide-react'\nimport romanticBg from '../../assets/romantic-background.png'\n\n// \u56fe\u7247\u9884\u52a0\u8f7d Hook\nconst useImagePreloader = (imageUrls) => {\n  const [loadedImages, setLoadedImages] = useState(new Set())\n  const [failedImages, setFailedImages] = useState(new Set())\n\n  useEffect(() => {\n    const loadImage = (url) => {\n      return new Promise((resolve) => {\n        const img = new Image()\n        img.onload = () => {\n          setLoadedImages(prev => new Set([...prev, url]))\n          resolve(true)\n        }\n        img.onerror = () => {\n          setFailedImages(prev => new Set([...prev, url]))\n          resolve(false)\n        }\n        img.src = url\n      })\n    }\n\n    const allImages = imageUrls.flat()\n    allImages.forEach(loadImage)\n  }, [imageUrls])\n\n  return { loadedImages, failedImages }\n}\n\nconst MemoryPage = () => {\n    const [activeCategory, setActiveCategory] = useState('all')\n    const [showForm, setShowForm] = useState(false)\n    const [memories, setMemories] = useState([\n        {\n            id: 1,\n            title: \"\u544a\u767d\u306e\u65e5\",\n            date: \"2025-06-06\",\n            location: \"\u4e2d\u592e\u516c\u56ed\",\n            description: \"\u90a3\u4e2a\u8ba9\u6211\u4eec\u5fc3\u52a8\u7684\u7f8e\u597d\u65f6\u523b\uff0c\u4ece\u6b64\u5f00\u59cb\u4e86\u6211\u4eec\u7684\u7231\u60c5\u6545\u4e8b\u3002\",\n            category: \"\u7279\u522b\u65e5\u5b50\",\n            images: [\"img/20250606.jpg\", \"img/20250606-2.jpg\"] // \u652f\u6301\u591a\u5f20\u56fe\u7247\n        },\n        {\n            id: 2,\n            title: \"\u7b2c\u4e00\u6b21\u7ea6\u4f1a\",\n            date: \"2025-06-10\",\n            location: \"\u72ee\u5c71\u516c\u56ed\",\n            description: \"\u7d27\u5f20\u53c8\u5174\u594b\u7684\u7b2c\u4e00\u6b21\u7ea6\u4f1a\uff0c\u6bcf\u4e00\u4e2a\u7ec6\u8282\u90fd\u6df1\u6df1\u5370\u5728\u5fc3\u91cc\u3002\",\n            category: \"\u7ea6\u4f1a\",\n            images: [\"img/20250610.jpg\", \"img/20250610-2.jpg\", \"img/20250610-3.jpg\"]\n        },\n        {\n            id: 3,\n            title: \"\u516c\u56ed\u6563\u6b65\",\n            date: \"2025-06-13\",\n            location: \"\u77f3\u6e56\u516c\u56ed\",\n            description: \"\u624b\u7275\u624b\u6f2b\u6b65\u5728\u516c\u56ed\u91cc\uff0c\u4eab\u53d7\u7740\u53ea\u5c5e\u4e8e\u6211\u4eec\u7684\u751c\u871c\u65f6\u5149\u3002\",\n            category: \"\u7ea6\u4f1a\",\n            images: [\"img/20250613.jpg\"]\n        },\n        {\n            id: 4,\n            title: \"\u6d6a\u6f2b\u665a\u9910\",\n            date: \"2025-06-20\",\n            location: \"\u661f\u7a7a\u9910\u5385\",\n            description: \"\u70db\u5149\u665a\u9910\uff0c\u661f\u7a7a\u4e0b\u7684\u6d6a\u6f2b\u7ea6\u5b9a\u3002\",\n            category: \"\u7ea6\u4f1a\",\n            images: [\"https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=800\", \"https://images.unsplash.com/photo-1551218808-94e220e084d2?w=800\"]\n        }\n    ])\n\n    // \u83b7\u53d6\u6240\u6709\u56fe\u7247URL\u7528\u4e8e\u9884\u52a0\u8f7d\n    const allImageUrls = memories.map(memory => memory.images)\n    const { loadedImages, failedImages } = useImagePreloader(allImageUrls)"}","mcp_server_name":"","mcp_tool_name":""}},{"id":0,"type":0,"content":"[构思]

